        private void FireSplitGuiLing(Vector3 spawnPos, Vector3 direction, GameObject targetEnemy)
        {
            GameObject splitGuiLing = PoolHelper.Get(poolName, spawnPos);
            if (splitGuiLing == null)
            {
                Debug.LogWarning($"[GuiLingBase] 从对象池 {poolName} 获取分裂弹失败");
                return;
            }
            var guiLingBase = splitGuiLing.GetComponent<GuiLingBase>();
            guiLingBase.poolName = poolName;
            guiLingBase.SetTargetAndLaunch(targetEnemy.transform, direction);
            guiLingBase.SetDamageData(_isMine, _damage * splitDamageMultiplier, _criticalChance, _criticalMultiplier, _element);
            guiLingBase.SetSplitData(false, 0);
            guiLingBase.SetCastNetwork(_castNetwork);

            if (_isMine && _castNetwork != null && !_isTest)
            {
                _castNetwork.BroadcastSplitGuiLingCast(spawnPos, direction, targetEnemy, (int)_element);
            }
        }

        private static void SetLayerRecursively(GameObject obj, int layer)
        {
            obj.layer = layer;
            foreach (Transform child in obj.transform)
                SetLayerRecursively(child.gameObject, layer);
        }

        private static int GetLayerFromMask(LayerMask mask) { return (int)Mathf.Log(mask.value, 2); }

        private bool IsPointVisibleFromCamera(Vector3 point)
        {
            var cam = Camera.main;
            if (cam == null) return false;
            var dir = point - cam.transform.position;
            var distance = dir.magnitude;
            dir.Normalize();
            if (!Physics.Raycast(cam.transform.position, dir, out var hit, distance,
                    Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
                return false;
            return hit.collider == _collider;
        }
    }
}
```

**⚠️ Performance issues:**
- **`IsTargetDead()` → `_target.GetComponent<EnemyBase>()` called every `FixedUpdate`** while in tracking phase — `GetComponent` every physics frame for every active GuiLing projectile. Should cache the `EnemyBase` reference on target acquisition.
- **`TryAcquireNewTarget` and `SplitToNearestEnemies` → `GetComponentInParent<EnemyBase>()` in loops** — repeated reflective component lookups per enemy in the OverlapSphere results.
- **`OnTriggerEnter` → `GetRootEnemyTransform` → `GetComponentInParent<EnemyBase>()`** per hit (hot path).
- **`FireSplitGuiLing` → `splitGuiLing.GetComponent<GuiLingBase>()`** per split bullet.
- **`SetTargetAndLaunch` → `trail.GetComponent<ParticleSystem>()`** inside `foreach (var trail in trails)` — GetComponent per trail, every launch.
- **`StartCoroutine(DelayedReturnToPool(0f))` with delay `0f`** — allocates a coroutine for an *immediate* (zero-delay) return. Pointless coroutine overhead; could call `ReturnToPool()` directly. Allocates an `IEnumerator` object per hit.
- **`IsPointVisibleFromCamera` → `Camera.main` + `Physics.Raycast`** per hit — `Camera.main` historically does a `FindObjectByTag` (cached in 2022.3 but still a property access), and a raycast per projectile hit.
- **`SetLayerRecursively`** recursion over all children on every hit when VFX layer is used — fine for small VFX but walk-heavy for large hierarchies.
- Good: caches `_enemyLayerMask` and `_sortByDistance` in `Awake`; uses `PoolHelper` (zero-GC); uses `DamageEventArgs.GetShared` (pooled args).

