using Core;
using Core;
using UnityEngine;

namespace Controllers.Combat
{
    /// <summary>
    /// GuiLing 击中特效自动归还脚本
    /// </summary>
    public class GuiLingHit : MonoBehaviour
    {
        [SerializeField] private string poolName;

        private ParticleSystem _ps;

        private void Awake()
        {
            _ps = GetComponentInChildren<ParticleSystem>();
        }

        private void OnEnable()
        {
            if (_ps != null)
            {
                _ps.time = 0f;
                _ps.Play();
            }

            float duration = 2f;
            if (_ps != null)
            {
                float mainDuration = _ps.main.duration;
                float lifetime = _ps.main.startLifetime.constantMax;
                duration = Mathf.Max(mainDuration + lifetime, 0.5f);
            }

            Invoke(nameof(ReturnToPool), duration);
        }

        private void OnDisable()
        {
            CancelInvoke(nameof(ReturnToPool));
        }

        private void ReturnToPool()
        {
            if (!string.IsNullOrEmpty(poolName))
            {
                EventChannelLocator.MainContainer?.poolOperationChannel?.Raise(
                    PoolOperationData.CreateReturn(poolName, gameObject));
            }
            else
            {
                Destroy(gameObject);
            }
        }
    }
}
```

**⚠️ Performance issues:**
- **Uses the OLD event-channel path** `poolOperationChannel.Raise(PoolOperationData.CreateReturn(...))` instead of the zero-GC `PoolHelper.Return(poolName, gameObject)`. Inconsistent with `GuiLingBase` which uses `PoolHelper`. Every hit-VFX recycle allocates a `PoolOperationData`.
- **`Invoke(nameof(ReturnToPool), duration)`** — `Invoke` uses reflection/string lookup; minor but per-effect. A coroutine or tracked timer would be cleaner.
- `_ps.main` accessor allocates a `ParticleSystem.MainModule` struct each access (value type, no heap alloc, but repeated access to `.main` has overhead; could cache).
- Duplicate `using Core;`.

